namespace Bokhyllan.Api.Data.Entities;

public sealed class Book
{
    public Guid Id { get; set; }   
    public string Title { get; set; } = "";
    public string Author { get; set; } = "";
    public int? Year { get; set; }
    public string? Isbn { get; set; }
    public string Description { get; set; } = "";

    // The file name is generated by us (a Guid), never taken from the uploaded file.
    public string? CoverFileName { get; set; }
    public string? CoverContentType { get; set; }
    public string? OpenLibraryWorkId { get; set; }
    public DateTimeOffset CreatedAt { get; set; }
    public DateTimeOffset UpdatedAt { get; set; }

    // Mapped to PostgreSQL's hidden xmin column, which changes on every UPDATE.
    // Used for optimistic concurrency: "save only if nobody changed the row since I read it".
    public uint Version { get; set; }
    public List<Review> Reviews { get; set; } = [];

}
